import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { isTokenExpired } from '../js/tokenManipulate.js';

const navigate = useNavigate();

export async function handleLogoutAcc(token, setAuthToken) {
    localStorage.removeItem('authToken')
    localStorage.setItem('name', 'Unknow')
    localStorage.setItem('email', '')
    localStorage.setItem('profile', '')
    setAuthToken(false);
    await axios.post('/logoutServer').then(res => {
        if (token && isTokenExpired()) {
            navigate('/home')
            return
        }
        return (res.data.theme, res.data.title, res.data.content)
    }).catch(err => {
        console.log('error')
        return ('danger', 'Error', "Unable to logout")
    })
}
